/** Bundled staff office + salary SQL for Vercel (generated — run scripts/bundle-staff-office-sql-chunks.mjs). */
export const STAFF_OFFICE_ENSURE_SCHEMA_CHUNKS = ["-- Idempotent schema ensure — called by admin RPCs so tables exist before any read/write.\n\nCREATE OR REPLACE FUNCTION public._ensure_staff_attendance_office_schema()\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  IF to_regclass('public.staff_attendance_offices') IS NULL THEN\n    CREATE TABLE public.staff_attendance_offices (\n      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n      name text NOT NULL,\n      address text,\n      latitude double precision NOT NULL,\n      longitude double precision NOT NULL,\n      radius_meters integer NOT NULL DEFAULT 200 CHECK (radius_meters BETWEEN 25 AND 5000),\n      max_gps_accuracy_m numeric DEFAULT 100 CHECK (max_gps_accuracy_m IS NULL OR max_gps_accuracy_m > 0),\n      require_face boolean NOT NULL DEFAULT true,\n      require_geo boolean NOT NULL DEFAULT true,\n      is_active boolean NOT NULL DEFAULT true,\n      created_at timestamptz NOT NULL DEFAULT now(),\n      updated_at timestamptz NOT NULL DEFAULT now()\n    );\n  END IF;\n\n  IF to_regclass('public.staff_office_assignments') IS NULL THEN\n    CREATE TABLE public.staff_office_assignments (\n      employee_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n      office_id uuid NOT NULL REFERENCES public.staff_attendance_offices(id) ON DELETE RESTRICT,\n      assigned_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,\n      assigned_at timestamptz NOT NULL DEFAULT now()\n    );\n    CREATE INDEX IF NOT EXISTS idx_staff_office_assignments_office\n      ON public.staff_office_assignments (office_id);\n  END IF;\n\n  ALTER TABLE public.staff_attendance_offices ENABLE ROW LEVEL SECURITY;\n  ALTER TABLE public.staff_office_assignments ENABLE ROW LEVEL SECURITY;\n\n  DROP POLICY IF EXISTS \"Admins manage staff_attendance_offices\" ON public.staff_attendance_offices;\n  CREATE POLICY \"Admins manage staff_attendance_offices\" ON public.staff_attendance_offices\n  FOR ALL TO authenticated\n  USING (\n    public.has_role(auth.uid(), 'admin'::public.app_role)\n    OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n  )\n  WITH CHECK (\n    public.has_role(auth.uid(), 'admin'::public.app_role)\n    OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n  );\n\n  DROP POLICY IF EXISTS \"Staff read assigned office\" ON public.staff_attendance_offices;\n  CREATE POLICY \"Staff read assigned office\" ON public.staff_attendance_offices\n  FOR SELECT TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.staff_office_assignments a\n      WHERE a.employee_id = auth.uid() AND a.office_id = staff_attendance_offices.id\n    )\n  );\n\n  DROP POLICY IF EXISTS \"Admins manage staff_office_assignments\" ON public.staff_office_assignments;\n  CREATE POLICY \"Admins manage staff_office_assignments\" ON public.staff_office_assignments\n  FOR ALL TO authenticated\n  USING (\n    public.has_role(auth.uid(), 'admin'::public.app_role)\n    OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n  )\n  WITH CHECK (\n    public.has_role(auth.uid(), 'admin'::public.app_role)\n    OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n  );\n\n  DROP POLICY IF EXISTS \"Staff read own office assignment\" ON public.staff_office_assignments;\n  CREATE POLICY \"Staff read own office assignment\" ON public.staff_office_assignments\n  FOR SELECT TO authenticated\n  USING (employee_id = auth.uid());\n\n  GRANT SELECT, INSERT, UPDATE, DELETE ON public.staff_attendance_offices TO authenticated;\n  GRANT SELECT, INSERT, UPDATE, DELETE ON public.staff_office_assignments TO authenticated;\n\n  IF to_regclass('public.employee_attendance') IS NOT NULL THEN\n    ALTER TABLE public.employee_attendance\n      ADD COLUMN IF NOT EXISTS office_id uuid REFERENCES public.staff_attendance_offices(id) ON DELETE SET NULL,\n      ADD COLUMN IF NOT EXISTS check_in_distance_m numeric,\n      ADD COLUMN IF NOT EXISTS check_out_distance_m numeric,\n      ADD COLUMN IF NOT EXISTS check_in_gps_accuracy_m numeric,\n      ADD COLUMN IF NOT EXISTS check_out_gps_accuracy_m numeric,\n      ADD COLUMN IF NOT EXISTS verification_flags jsonb NOT NULL DEFAULT '{}'::jsonb;\n  END IF;\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public._ensure_staff_attendance_office_schema() TO authenticated;"];
export function staffOfficeEnsureSchemaSql(): string {
  return STAFF_OFFICE_ENSURE_SCHEMA_CHUNKS.join("");
}

export const STAFF_OFFICE_ADMIN_RPC_CHUNKS = ["-- Admin RPCs for office CRUD (SECURITY DEFINER — auto-creates schema via _ensure_staff_attendance_office_schema).\n-- Run aws/scripts/85-rds-staff-attendance-offices-ensure-schema.sql before this file when applying manually.\n\nCREATE OR REPLACE FUNCTION public._assert_admin_attendance_offices()\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';\n  END IF;\n  IF NOT (\n    public.has_role(auth.uid(), 'admin'::public.app_role)\n    OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n  ) THEN\n    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';\n  END IF;\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_list_staff_attendance_offices(p_active_only boolean DEFAULT false)\nRETURNS jsonb\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  PERFORM public._ensure_staff_attendance_office_schema();\n  PERFORM public._assert_admin_attendance_offices();\n  RETURN coalesce(\n    (SELECT jsonb_agg(to_jsonb(o) ORDER BY o.name)\n     FROM public.staff_attendance_offices o\n     WHERE NOT coalesce(p_active_only, false) OR o.is_active IS TRUE),\n    '[]'::jsonb\n  );\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_upsert_staff_attendance_office(\n  p_id uuid DEFAULT NULL,\n  p_name text DEFAULT NULL,\n  p_address text DEFAULT NULL,\n  p_latitude double precision DEFAULT NULL,\n  p_longitude double precision DEFAULT NULL,\n  p_radius_meters integer DEFAULT 200,\n  p_max_gps_accuracy_m numeric DEFAULT 100,\n  p_require_face boolean DEFAULT true,\n  p_require_geo boolean DEFAULT true,\n  p_is_active boolean DEFAULT true\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_row public.staff_attendance_offices%ROWTYPE;\nBEGIN\n  PERFORM public._ensure_staff_attendance_office_schema();\n  PERFORM public._assert_admin_attendance_offices();\n\n  IF p_name IS NULL OR trim(p_name) = '' THEN\n    RAISE EXCEPTION 'Office name is required';\n  END IF;\n  IF p_latitude IS NULL OR p_longitude IS NULL THEN\n    RAISE EXCEPTION 'Latitude and longitude are required';\n  END IF;\n\n  IF p_id IS NULL THEN\n    INSERT INTO public.staff_attendance_offices (\n      name, address, latitude, longitude, radius_meters,\n      max_gps_accuracy_m, require_face, require_geo, is_active, updated_at\n    )\n    VALUES (\n      trim(p_name),\n      nullif(trim(coalesce(p_address, '')), ''),\n      p_latitude,\n      p_longitude,\n      coalesce(p_radius_meters, 200),\n      p_max_gps_accuracy_m,\n      coalesce(p_require_face, true),\n      coalesce(p_require_geo, true),\n      coalesce(p_is_active, true),\n      now()\n    )\n    RETURNING * INTO v_row;\n  ELSE\n    UPDATE public.staff_attendance_offices\n    SET\n      name = trim(p_name),\n      address = nullif(trim(coalesce(p_address, '')), ''),\n      latitude = p_latitude,\n      longitude = p_longitude,\n      radius_meters = coalesce(p_radius_meters, 200),\n      max_gps_accuracy_m = p_max_gps_accuracy_m,\n      require_face = coalesce(p_require_face, true),\n      require_geo = coalesce(p_require_geo, true),\n      is_active = coalesce(p_is_active, true),\n      updated_at = now()\n    WHERE id = p_id\n    RETURNING * INTO v_row;\n\n    IF NOT FOUND THEN\n      RAISE EXCEPTION 'Office not found';\n    END IF;\n  END IF;\n\n  RETURN to_jsonb(v_row);\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_delete_staff_attendance_office(p_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  PERFORM public._ensure_staff_attendance_office_schema();\n  PERFORM public._assert_admin_attendance_offices();\n\n  IF p_id IS NULL THEN\n    RAISE EXCEPTION 'Office id is required';\n  END IF;\n\n  DELETE FROM public.staff_attendance_offices WHERE id = p_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Office not found or still assigned to employees';\n  END IF;\n\n  RETURN jsonb_build_object('ok', true, 'id', p_id);\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_assign_staff_office(\n  p_employee_id uuid,\n  p_office_id uuid\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_row public.staff_office_assignments%ROWTYPE;\nBEGIN\n  PERFORM public._ensure_staff_attendance_office_schema();\n  PERFORM public._assert_admin_attendance_offices();\n\n  IF p_employee_id IS NULL OR p_office_id IS NULL THEN\n    RAISE EXCEPTION 'Employee and office are required';\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1 FROM public.staff_attendance_offices o\n    WHERE o.id = p_office_id AND o.is_active IS TRUE\n  ) THEN\n    RAISE EXCEPTION 'Office not found or inactive';\n  END IF;\n\n  INSERT INTO public.staff_office_assignments (employee_id, office_id, assigned_by, assigned_at)\n  VALUES (p_employee_id, p_office_id, auth.uid(), now())\n  ON CONFLICT (employee_id) DO UPDATE\n  SET office_id = EXCLUDED.office_id,\n      assigned_by = auth.uid(),\n      assigned_at = now()\n  RETURNING * INTO v_row;\n\n  RETURN to_jsonb(v_row);\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_remove_staff_office_assignment(p_employee_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  PERFORM public._ensure_staff_attendance_office_schema();\n  PERFORM public._assert_admin_attendance_offices();\n\n  IF p_employee_id IS NULL THEN\n    RAISE EXCEPTION 'Employee id is required';\n  END IF;\n\n  DELETE FROM public.staff_office_assignments WHERE employee_id = p_employee_id;\n\n  RETURN jsonb_build_object('ok', true, 'employee_id', p_employee_id);\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_list_staff_office_assignments()\nRETURNS jsonb\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  PERFORM public._ensure_staff_attendance_office_schema();\n  PERFORM public._assert_admin_attendance_offices();\n  RETURN coalesce(\n    (SELECT jsonb_agg(to_jsonb(a) ORDER BY a.assigned_at DESC)\n     FROM public.staff_office_assignments a),\n    '[]'::jsonb\n  );\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.admin_list_staff_attendance_offices(boolean) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.admin_upsert_staff_attendance_office(\n  uuid, text, text, double precision, double precision, integer, numeric, boolean, boolean, boolean\n) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.admin_delete_staff_attendance_office(uuid) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.admin_assign_staff_office(uuid, uuid) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.admin_remove_staff_office_assignment(uuid) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.admin_list_staff_office_assignments() TO authenticated;"];
export function staffOfficeAdminRpcSql(): string {
  return STAFF_OFFICE_ADMIN_RPC_CHUNKS.join("");
}

export const STAFF_OFFICE_SELF_RPC_CHUNKS = ["-- Staff self attendance RPCs: per-employee office lookup via staff_office_assignments.\n-- Requires 85 (schema) + 83 (admin RPCs). Run after assignments exist.\n\nCREATE OR REPLACE FUNCTION public._staff_office_for_employee(p_employee_id uuid)\nRETURNS TABLE (\n  office_id uuid,\n  name text,\n  address text,\n  latitude double precision,\n  longitude double precision,\n  radius_meters integer,\n  max_gps_accuracy_m numeric,\n  require_face boolean,\n  require_geo boolean\n)\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT\n    o.id,\n    o.name,\n    o.address,\n    o.latitude,\n    o.longitude,\n    o.radius_meters,\n    o.max_gps_accuracy_m,\n    o.require_face,\n    o.require_geo\n  FROM public.staff_office_assignments a\n  JOIN public.staff_attendance_offices o ON o.id = a.office_id\n  WHERE a.employee_id = p_employee_id\n    AND o.is_active IS TRUE\n  LIMIT 1;\n$$;\n\nCREATE OR REPLACE FUNCTION public.staff_self_attendance_status()\nRETURNS jsonb\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_uid uuid := auth.uid();\n  v_today date := (timezone('Asia/Kolkata', now()))::date;\n  v_row public.employee_attendance%ROWTYPE;\n  v_minutes integer := public._ist_minutes_now();\n  v_office record;\n  v_check_in_start constant integer := 600;\n  v_check_out_start constant integer := 1080;\nBEGIN\n  IF v_uid IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';\n  END IF;\n\n  IF NOT public.has_role(v_uid, 'staff'::public.app_role) THEN\n    RAISE EXCEPTION 'Staff role required' USING ERRCODE = '42501';\n  END IF;\n\n  SELECT * INTO v_office FROM public._staff_office_for_employee(v_uid) LIMIT 1;\n\n  SELECT * INTO v_row\n  FROM public.employee_attendance ea\n  WHERE ea.employee_id = v_uid AND ea.attendance_date = v_today\n  LIMIT 1;\n\n  RETURN jsonb_build_object(\n    'attendance_date', v_today,\n    'ist_minutes', v_minutes,\n    'check_in_at', v_row.check_in_at,\n    'check_out_at', v_row.check_out_at,\n    'has_check_in', v_row.check_in_at IS NOT NULL,\n    'has_check_out', v_row.check_out_at IS NOT NULL,\n    'can_check_in',\n      v_office.office_id IS NOT NULL\n      AND v_row.check_in_at IS NULL\n      AND v_minutes >= v_check_in_start\n      AND v_minutes < v_check_out_start,\n    'can_check_out',\n      v_office.office_id IS NOT NULL\n      AND v_row.check_in_at IS NOT NULL\n      AND v_row.check_out_at IS NULL\n      AND v_minutes >= v_check_out_start,\n    'check_in_opens_at', '10:00',\n    'check_out_opens_at', '18:00',\n    'office_assigned', v_office.office_id IS NOT NULL,\n    'office', CASE WHEN v_office.office_id IS NULL THEN NULL ELSE jsonb_build_object(\n      'id', v_office.office_id,\n      'name', v_office.name,\n      'address', v_office.address,\n      'latitude', v_office.latitude,\n      'longitude', v_office.longitude,\n      'radius_meters', v_office.radius_meters,\n      'max_gps_accuracy_m', v_office.max_gps_accuracy_m,\n      'require_face', v_office.require_face,\n      'require_geo', v_office.require_geo\n    ) END\n  );\nEND;\n$$;\n\nDROP FUNCTION IF EXISTS public.staff_self_check_in(double precision, double precision, numeric);\n","CREATE OR REPLACE FUNCTION public.staff_self_check_in(\n  p_latitude double precision,\n  p_longitude double precision,\n  p_face_score numeric,\n  p_gps_accuracy_m numeric DEFAULT NULL\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_uid uuid := auth.uid();\n  v_today date := (timezone('Asia/Kolkata', now()))::date;\n  v_minutes integer := public._ist_minutes_now();\n  v_office record;\n  v_distance double precision;\n  v_profile_image text;\n  v_flags jsonb;\n  v_check_in_start constant integer := 600;\n  v_check_out_start constant integer := 1080;\n  v_min_face_score constant numeric := 0.55;\nBEGIN\n  IF v_uid IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';\n  END IF;\n\n  IF NOT public.has_role(v_uid, 'staff'::public.app_role) THEN\n    RAISE EXCEPTION 'Staff role required' USING ERRCODE = '42501';\n  END IF;\n\n  SELECT * INTO v_office FROM public._staff_office_for_employee(v_uid) LIMIT 1;\n  IF v_office.office_id IS NULL THEN\n    RAISE EXCEPTION 'No office location assigned. Contact admin.';\n  END IF;\n\n  IF v_minutes < v_check_in_start OR v_minutes >= v_check_out_start THEN\n    RAISE EXCEPTION 'Check-in is only available from 10:00 AM to 6:00 PM IST';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.employee_attendance ea\n    WHERE ea.employee_id = v_uid AND ea.attendance_date = v_today AND ea.check_in_at IS NOT NULL\n  ) THEN\n    RAISE EXCEPTION 'Already checked in for today';\n  END IF;\n\n  IF v_office.require_face THEN\n    SELECT profile_image_url INTO v_profile_image\n    FROM public.admin_staff\n    WHERE id = v_uid OR user_id = v_uid\n    LIMIT 1;\n    IF v_profile_image IS NULL OR trim(v_profile_image) = '' THEN\n      RAISE EXCEPTION 'Upload a profile photo before using face attendance';\n    END IF;\n    IF p_face_score IS NULL OR p_face_score < v_min_face_score THEN\n      RAISE EXCEPTION 'Face verification failed. Align your face with the camera.';\n    END IF;\n  END IF;\n\n  IF v_office.require_geo THEN\n    IF p_latitude IS NULL OR p_longitude IS NULL THEN\n      RAISE EXCEPTION 'Location is required';\n    END IF;\n    IF v_office.max_gps_accuracy_m IS NOT NULL AND p_gps_accuracy_m IS NOT NULL\n       AND p_gps_accuracy_m > v_office.max_gps_accuracy_m THEN\n      RAISE EXCEPTION 'GPS signal too weak or unreliable (accuracy % m). Disable mock location and try again.', round(p_gps_accuracy_m::numeric, 0);\n    END IF;\n    v_distance := public._haversine_meters(p_latitude, p_longitude, v_office.latitude, v_office.longitude);\n    IF v_distance > v_office.radius_meters THEN\n      RAISE EXCEPTION '%', format(\n        'You are %s m from %s (max %s m)',\n        round(v_distance::numeric, 0),\n        v_office.name,\n        v_office.radius_meters\n      );\n    END IF;\n  END IF;\n\n  v_flags := jsonb_build_object(\n    'check_in', jsonb_build_object(\n      'distance_m', round(coalesce(v_distance, 0)::numeric, 2),\n      'gps_accuracy_m', p_gps_accuracy_m,\n      'face_score', p_face_score,\n      'office_id', v_office.office_id,\n      'office_name', v_office.name,\n      'verified_at', now()\n    )\n  );\n\n  INSERT INTO public.employee_attendance (\n    employee_id, attendance_date, status, check_in_at,\n    check_in_latitude, check_in_longitude, check_in_face_score, check_in_method,\n    check_in_distance_m, check_in_gps_accuracy_m, office_id, verification_flags,\n    marked_by, updated_at\n  )\n  VALUES (\n    v_uid, v_today, 'present', now(),\n    p_latitude, p_longitude, p_face_score, 'geo_face',\n    round(coalesce(v_distance, 0)::numeric, 2), p_gps_accuracy_m, v_office.office_id, v_flags,\n    v_uid, now()\n  )\n  ON CONFLICT (employee_id, attendance_date) DO NOTHING;\n\n  IF NOT FOUND THEN\n    UPDATE public.employee_attendance\n    SET\n      status = 'present',\n      check_in_at = COALESCE(check_in_at, now()),\n      check_in_latitude = COALESCE(check_in_latitude, p_latitude),\n      check_in_longitude = COALESCE(check_in_longitude, p_longitude),\n      check_in_face_score = COALESCE(check_in_face_score, p_face_score),\n      check_in_method = COALESCE(check_in_method, 'geo_face'),\n      check_in_distance_m = COALESCE(check_in_distance_m, round(coalesce(v_distance, 0)::numeric, 2)),\n      check_in_gps_accuracy_m = COALESCE(check_in_gps_accuracy_m, p_gps_accuracy_m),\n      office_id = COALESCE(office_id, v_office.office_id),\n      verification_flags = verification_flags || v_flags,\n      updated_at = now()\n    WHERE employee_id = v_uid AND attendance_date = v_today AND check_in_at IS NULL;\n\n    IF NOT FOUND THEN\n      RAISE EXCEPTION 'Already checked in for today';\n    END IF;\n  END IF;\n\n  RETURN jsonb_build_object('ok', true, 'action', 'check_in', 'office_id', v_office.office_id);\nEND;\n$$;\n\nDROP FUNCTION IF EXISTS public.staff_self_check_out(double precision, double precision, numeric);\n","CREATE OR REPLACE FUNCTION public.staff_self_check_out(\n  p_latitude double precision,\n  p_longitude double precision,\n  p_face_score numeric,\n  p_gps_accuracy_m numeric DEFAULT NULL\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_uid uuid := auth.uid();\n  v_today date := (timezone('Asia/Kolkata', now()))::date;\n  v_minutes integer := public._ist_minutes_now();\n  v_office record;\n  v_distance double precision;\n  v_profile_image text;\n  v_flags jsonb;\n  v_check_out_start constant integer := 1080;\n  v_min_face_score constant numeric := 0.55;\nBEGIN\n  IF v_uid IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';\n  END IF;\n\n  IF NOT public.has_role(v_uid, 'staff'::public.app_role) THEN\n    RAISE EXCEPTION 'Staff role required' USING ERRCODE = '42501';\n  END IF;\n\n  SELECT * INTO v_office FROM public._staff_office_for_employee(v_uid) LIMIT 1;\n  IF v_office.office_id IS NULL THEN\n    RAISE EXCEPTION 'No office location assigned. Contact admin.';\n  END IF;\n\n  IF v_minutes < v_check_out_start THEN\n    RAISE EXCEPTION 'Check-out opens at 6:00 PM IST';\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1 FROM public.employee_attendance ea\n    WHERE ea.employee_id = v_uid AND ea.attendance_date = v_today AND ea.check_in_at IS NOT NULL\n  ) THEN\n    RAISE EXCEPTION 'Check in first before checking out';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.employee_attendance ea\n    WHERE ea.employee_id = v_uid AND ea.attendance_date = v_today AND ea.check_out_at IS NOT NULL\n  ) THEN\n    RAISE EXCEPTION 'Already checked out for today';\n  END IF;\n\n  IF v_office.require_face THEN\n    SELECT profile_image_url INTO v_profile_image FROM public.admin_staff\n    WHERE id = v_uid OR user_id = v_uid LIMIT 1;\n    IF v_profile_image IS NULL OR trim(v_profile_image) = '' THEN\n      RAISE EXCEPTION 'Upload a profile photo before using face attendance';\n    END IF;\n    IF p_face_score IS NULL OR p_face_score < v_min_face_score THEN\n      RAISE EXCEPTION 'Face verification failed. Align your face with the camera.';\n    END IF;\n  END IF;\n\n  IF v_office.require_geo THEN\n    IF p_latitude IS NULL OR p_longitude IS NULL THEN\n      RAISE EXCEPTION 'Location is required';\n    END IF;\n    IF v_office.max_gps_accuracy_m IS NOT NULL AND p_gps_accuracy_m IS NOT NULL\n       AND p_gps_accuracy_m > v_office.max_gps_accuracy_m THEN\n      RAISE EXCEPTION 'GPS signal too weak or unreliable (accuracy % m). Disable mock location and try again.', round(p_gps_accuracy_m::numeric, 0);\n    END IF;\n    v_distance := public._haversine_meters(p_latitude, p_longitude, v_office.latitude, v_office.longitude);\n    IF v_distance > v_office.radius_meters THEN\n      RAISE EXCEPTION '%', format(\n        'You are %s m from %s (max %s m)',\n        round(v_distance::numeric, 0),\n        v_office.name,\n        v_office.radius_meters\n      );\n    END IF;\n  END IF;\n\n  v_flags := jsonb_build_object(\n    'check_out', jsonb_build_object(\n      'distance_m', round(coalesce(v_distance, 0)::numeric, 2),\n      'gps_accuracy_m', p_gps_accuracy_m,\n      'face_score', p_face_score,\n      'office_id', v_office.office_id,\n      'office_name', v_office.name,\n      'verified_at', now()\n    )\n  );\n\n  UPDATE public.employee_attendance\n  SET\n    check_out_at = now(),\n    check_out_latitude = p_latitude,\n    check_out_longitude = p_longitude,\n    check_out_face_score = p_face_score,\n    check_out_method = 'geo_face',\n    check_out_distance_m = round(coalesce(v_distance, 0)::numeric, 2),\n    check_out_gps_accuracy_m = p_gps_accuracy_m,\n    verification_flags = verification_flags || v_flags,\n    updated_at = now()\n  WHERE employee_id = v_uid AND attendance_date = v_today AND check_out_at IS NULL;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Could not check out';\n  END IF;\n\n  RETURN jsonb_build_object('ok', true, 'action', 'check_out');\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public._staff_office_for_employee(uuid) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.staff_self_attendance_status() TO authenticated;\nGRANT EXECUTE ON FUNCTION public.staff_self_check_in(double precision, double precision, numeric, numeric) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.staff_self_check_out(double precision, double precision, numeric, numeric) TO authenticated;"];
export function staffOfficeSelfAttendanceRpcSql(): string {
  return STAFF_OFFICE_SELF_RPC_CHUNKS.join("");
}

export const STAFF_SALARY_BASE_CHUNKS = ["-- Staff salary: payment setup, monthly generation, and payout status (admin).\n\nCREATE TABLE IF NOT EXISTS public.staff_salary_setup (\n  employee_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n  basic_salary numeric(12, 2) NOT NULL DEFAULT 0 CHECK (basic_salary >= 0),\n  hra numeric(12, 2) NOT NULL DEFAULT 0 CHECK (hra >= 0),\n  special_allowance numeric(12, 2) NOT NULL DEFAULT 0 CHECK (special_allowance >= 0),\n  other_allowances numeric(12, 2) NOT NULL DEFAULT 0 CHECK (other_allowances >= 0),\n  pf_deduction numeric(12, 2) NOT NULL DEFAULT 0 CHECK (pf_deduction >= 0),\n  tax_deduction numeric(12, 2) NOT NULL DEFAULT 0 CHECK (tax_deduction >= 0),\n  other_deductions numeric(12, 2) NOT NULL DEFAULT 0 CHECK (other_deductions >= 0),\n  working_days_per_month integer NOT NULL DEFAULT 26 CHECK (working_days_per_month BETWEEN 1 AND 31),\n  payment_mode text NOT NULL DEFAULT 'bank_transfer'\n    CHECK (payment_mode IN ('bank_transfer', 'upi', 'cash')),\n  payment_notes text,\n  is_active boolean NOT NULL DEFAULT true,\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL\n);\n\nCREATE TABLE IF NOT EXISTS public.staff_salary_slips (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  employee_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  salary_month date NOT NULL,\n  present_days numeric(6, 2) NOT NULL DEFAULT 0,\n  absent_days numeric(6, 2) NOT NULL DEFAULT 0,\n  leave_days numeric(6, 2) NOT NULL DEFAULT 0,\n  half_days numeric(6, 2) NOT NULL DEFAULT 0,\n  gross_amount numeric(12, 2) NOT NULL DEFAULT 0,\n  attendance_deduction numeric(12, 2) NOT NULL DEFAULT 0,\n  total_deductions numeric(12, 2) NOT NULL DEFAULT 0,\n  net_amount numeric(12, 2) NOT NULL DEFAULT 0,\n  status text NOT NULL DEFAULT 'generated'\n    CHECK (status IN ('draft', 'generated', 'paid', 'cancelled')),\n  breakdown jsonb NOT NULL DEFAULT '{}'::jsonb,\n  payment_reference text,\n  generated_at timestamptz NOT NULL DEFAULT now(),\n  generated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,\n  paid_at timestamptz,\n  paid_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (employee_id, salary_month)\n);\n\nCREATE INDEX IF NOT EXISTS idx_staff_salary_slips_month\n  ON public.staff_salary_slips (salary_month DESC);\nCREATE INDEX IF NOT EXISTS idx_staff_salary_slips_status\n  ON public.staff_salary_slips (status);\n\nALTER TABLE public.staff_salary_setup ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.staff_salary_slips ENABLE ROW LEVEL SECURITY;\n\nDROP POLICY IF EXISTS \"Admins manage staff_salary_setup\" ON public.staff_salary_setup;\nCREATE POLICY \"Admins manage staff_salary_setup\" ON public.staff_salary_setup\nFOR ALL TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'admin'::public.app_role)\n  OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n)\nWITH CHECK (\n  public.has_role(auth.uid(), 'admin'::public.app_role)\n  OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n);\n\nDROP POLICY IF EXISTS \"Staff read own salary slips\" ON public.staff_salary_slips;\nCREATE POLICY \"Staff read own salary slips\" ON public.staff_salary_slips\nFOR SELECT TO authenticated\nUSING (employee_id = auth.uid());\n\nDROP POLICY IF EXISTS \"Admins manage staff_salary_slips\" ON public.staff_salary_slips;\nCREATE POLICY \"Admins manage staff_salary_slips\" ON public.staff_salary_slips\nFOR ALL TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'admin'::public.app_role)\n  OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n)\nWITH CHECK (\n  public.has_role(auth.uid(), 'admin'::public.app_role)\n  OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.staff_salary_setup TO authenticated;\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.staff_salary_slips TO authenticated;\n\nCREATE OR REPLACE FUNCTION public._admin_assert_salary_access()\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  IF NOT (\n    public.has_role(auth.uid(), 'admin'::public.app_role)\n    OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n  ) THEN\n    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';\n  END IF;\nEND;\n$$;\n","CREATE OR REPLACE FUNCTION public.admin_generate_staff_salary(\n  p_employee_id uuid,\n  p_salary_month date\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_month date := date_trunc('month', p_salary_month)::date;\n  v_month_end date := (date_trunc('month', p_salary_month) + interval '1 month - 1 day')::date;\n  v_setup public.staff_salary_setup%ROWTYPE;\n  v_present numeric := 0;\n  v_absent numeric := 0;\n  v_leave numeric := 0;\n  v_half numeric := 0;\n  v_gross numeric;\n  v_fixed_deductions numeric;\n  v_per_day numeric;\n  v_attendance_deduction numeric;\n  v_net numeric;\n  v_breakdown jsonb;\n  v_slip_id uuid;\nBEGIN\n  PERFORM public._admin_assert_salary_access();\n\n  IF p_employee_id IS NULL OR v_month IS NULL THEN\n    RAISE EXCEPTION 'Employee and salary month are required';\n  END IF;\n\n  SELECT * INTO v_setup\n  FROM public.staff_salary_setup s\n  WHERE s.employee_id = p_employee_id AND s.is_active IS TRUE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Payment setup missing for this staff member';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.staff_salary_slips ss\n    WHERE ss.employee_id = p_employee_id\n      AND ss.salary_month = v_month\n      AND ss.status IN ('generated', 'paid')\n  ) THEN\n    RAISE EXCEPTION 'Salary already generated for this month';\n  END IF;\n\n  SELECT\n    coalesce(sum(CASE WHEN ea.status = 'present' THEN 1 WHEN ea.status = 'half_day' THEN 0.5 ELSE 0 END), 0),\n    coalesce(sum(CASE WHEN ea.status = 'absent' THEN 1 ELSE 0 END), 0),\n    coalesce(sum(CASE WHEN ea.status = 'leave' THEN 1 ELSE 0 END), 0),\n    coalesce(sum(CASE WHEN ea.status = 'half_day' THEN 0.5 ELSE 0 END), 0)\n  INTO v_present, v_absent, v_leave, v_half\n  FROM public.employee_attendance ea\n  WHERE ea.employee_id = p_employee_id\n    AND ea.attendance_date >= v_month\n    AND ea.attendance_date <= v_month_end;\n\n  v_gross :=\n    coalesce(v_setup.basic_salary, 0)\n    + coalesce(v_setup.hra, 0)\n    + coalesce(v_setup.special_allowance, 0)\n    + coalesce(v_setup.other_allowances, 0);\n\n  v_fixed_deductions :=\n    coalesce(v_setup.pf_deduction, 0)\n    + coalesce(v_setup.tax_deduction, 0)\n    + coalesce(v_setup.other_deductions, 0);\n\n  v_per_day := CASE\n    WHEN v_setup.working_days_per_month > 0 THEN v_gross / v_setup.working_days_per_month\n    ELSE 0\n  END;\n\n  v_attendance_deduction := round((v_absent * v_per_day)::numeric, 2);\n  v_net := greatest(0, round((v_gross - v_fixed_deductions - v_attendance_deduction)::numeric, 2));\n\n  v_breakdown := jsonb_build_object(\n    'basic_salary', v_setup.basic_salary,\n    'hra', v_setup.hra,\n    'special_allowance', v_setup.special_allowance,\n    'other_allowances', v_setup.other_allowances,\n    'pf_deduction', v_setup.pf_deduction,\n    'tax_deduction', v_setup.tax_deduction,\n    'other_deductions', v_setup.other_deductions,\n    'working_days_per_month', v_setup.working_days_per_month,\n    'per_day_rate', round(v_per_day::numeric, 2),\n    'payment_mode', v_setup.payment_mode\n  );\n\n  INSERT INTO public.staff_salary_slips (\n    employee_id,\n    salary_month,\n    present_days,\n    absent_days,\n    leave_days,\n    half_days,\n    gross_amount,\n    attendance_deduction,\n    total_deductions,\n    net_amount,\n    status,\n    breakdown,\n    generated_by,\n    updated_at\n  )\n  VALUES (\n    p_employee_id,\n    v_month,\n    v_present,\n    v_absent,\n    v_leave,\n    v_half,\n    round(v_gross::numeric, 2),\n    v_attendance_deduction,\n    round((v_fixed_deductions + v_attendance_deduction)::numeric, 2),\n    v_net,\n    'generated',\n    v_breakdown,\n    auth.uid(),\n    now()\n  )\n  ON CONFLICT (employee_id, salary_month)\n  DO UPDATE SET\n    present_days = EXCLUDED.present_days,\n    absent_days = EXCLUDED.absent_days,\n    leave_days = EXCLUDED.leave_days,\n    half_days = EXCLUDED.half_days,\n    gross_amount = EXCLUDED.gross_amount,\n    attendance_deduction = EXCLUDED.attendance_deduction,\n    total_deductions = EXCLUDED.total_deductions,\n    net_amount = EXCLUDED.net_amount,\n    status = 'generated',\n    breakdown = EXCLUDED.breakdown,\n    generated_at = now(),\n    generated_by = auth.uid(),\n    updated_at = now()\n  WHERE public.staff_salary_slips.status NOT IN ('paid')\n  RETURNING id INTO v_slip_id;\n\n  RETURN jsonb_build_object(\n    'ok', true,\n    'slip_id', v_slip_id,\n    'employee_id', p_employee_id,\n    'salary_month', v_month,\n    'net_amount', v_net,\n    'status', 'generated'\n  );\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_mark_staff_salary_paid(\n  p_slip_id uuid,\n  p_payment_reference text DEFAULT NULL\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  PERFORM public._admin_assert_salary_access();\n\n  UPDATE public.staff_salary_slips\n  SET\n    status = 'paid',\n    payment_reference = nullif(trim(p_payment_reference), ''),\n    paid_at = now(),\n    paid_by = auth.uid(),\n    updated_at = now()\n  WHERE id = p_slip_id\n    AND status = 'generated';\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Salary slip not found or not in generated status';\n  END IF;\n\n  RETURN jsonb_build_object('ok', true, 'slip_id', p_slip_id, 'status', 'paid');\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.admin_generate_staff_salary(uuid, date) FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.admin_mark_staff_salary_paid(uuid, text) FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION public.admin_generate_staff_salary(uuid, date) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.admin_mark_staff_salary_paid(uuid, text) TO authenticated;"];
export function staffSalaryBaseSql(): string {
  return STAFF_SALARY_BASE_CHUNKS.join("");
}

export const STAFF_SALARY_ADVANCED_CHUNKS = ["-- Advanced automated salary: festivals, paid leave grants, half-day, overtime, approved leaves.\n\nALTER TABLE public.staff_salary_setup\n  ADD COLUMN IF NOT EXISTS paid_leaves_per_month integer NOT NULL DEFAULT 1\n    CHECK (paid_leaves_per_month >= 0),\n  ADD COLUMN IF NOT EXISTS standard_hours_per_day numeric NOT NULL DEFAULT 8\n    CHECK (standard_hours_per_day > 0),\n  ADD COLUMN IF NOT EXISTS overtime_multiplier numeric NOT NULL DEFAULT 1.5\n    CHECK (overtime_multiplier >= 1);\n\nALTER TABLE public.staff_salary_slips\n  ADD COLUMN IF NOT EXISTS overtime_hours numeric NOT NULL DEFAULT 0,\n  ADD COLUMN IF NOT EXISTS overtime_amount numeric NOT NULL DEFAULT 0,\n  ADD COLUMN IF NOT EXISTS festival_days numeric NOT NULL DEFAULT 0,\n  ADD COLUMN IF NOT EXISTS unpaid_leave_days numeric NOT NULL DEFAULT 0,\n  ADD COLUMN IF NOT EXISTS half_day_deduction numeric NOT NULL DEFAULT 0;\n\nCREATE TABLE IF NOT EXISTS public.staff_salary_holidays (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  holiday_date date NOT NULL UNIQUE,\n  name text NOT NULL,\n  is_paid boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_staff_salary_holidays_date\n  ON public.staff_salary_holidays (holiday_date);\n\nCREATE TABLE IF NOT EXISTS public.staff_paid_leave_grants (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  employee_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  salary_month date NOT NULL,\n  extra_paid_days numeric NOT NULL DEFAULT 0 CHECK (extra_paid_days >= 0),\n  reason text,\n  granted_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (employee_id, salary_month)\n);\n\nALTER TABLE public.staff_salary_holidays ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.staff_paid_leave_grants ENABLE ROW LEVEL SECURITY;\n\nDROP POLICY IF EXISTS \"Admins manage staff_salary_holidays\" ON public.staff_salary_holidays;\nCREATE POLICY \"Admins manage staff_salary_holidays\" ON public.staff_salary_holidays\nFOR ALL TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'admin'::public.app_role)\n  OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n)\nWITH CHECK (\n  public.has_role(auth.uid(), 'admin'::public.app_role)\n  OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n);\n\nDROP POLICY IF EXISTS \"Authenticated read staff_salary_holidays\" ON public.staff_salary_holidays;\nCREATE POLICY \"Authenticated read staff_salary_holidays\" ON public.staff_salary_holidays\nFOR SELECT TO authenticated\nUSING (true);\n\nDROP POLICY IF EXISTS \"Admins manage staff_paid_leave_grants\" ON public.staff_paid_leave_grants;\nCREATE POLICY \"Admins manage staff_paid_leave_grants\" ON public.staff_paid_leave_grants\nFOR ALL TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'admin'::public.app_role)\n  OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n)\nWITH CHECK (\n  public.has_role(auth.uid(), 'admin'::public.app_role)\n  OR public.has_role(auth.uid(), 'super_admin'::public.app_role)\n);\n\nDROP POLICY IF EXISTS \"Staff read own paid leave grants\" ON public.staff_paid_leave_grants;\nCREATE POLICY \"Staff read own paid leave grants\" ON public.staff_paid_leave_grants\nFOR SELECT TO authenticated\nUSING (employee_id = auth.uid());\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.staff_salary_holidays TO authenticated;\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.staff_paid_leave_grants TO authenticated;\n\nCREATE OR REPLACE FUNCTION public._staff_salary_worked_hours(\n  p_check_in timestamptz,\n  p_check_out timestamptz\n)\nRETURNS numeric\nLANGUAGE sql\nIMMUTABLE\nAS $$\n  SELECT CASE\n    WHEN p_check_in IS NULL OR p_check_out IS NULL THEN 0::numeric\n    WHEN p_check_out <= p_check_in THEN 0::numeric\n    ELSE round((EXTRACT(EPOCH FROM (p_check_out - p_check_in)) / 3600.0)::numeric, 2)\n  END;\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_list_staff_salary_holidays(p_salary_month date DEFAULT NULL)\nRETURNS jsonb\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_start date;\n  v_end date;\nBEGIN\n  PERFORM public._admin_assert_salary_access();\n\n  IF p_salary_month IS NULL THEN\n    RETURN coalesce((SELECT jsonb_agg(to_jsonb(h) ORDER BY h.holiday_date)\n      FROM public.staff_salary_holidays h), '[]'::jsonb);\n  END IF;\n\n  v_start := date_trunc('month', p_salary_month)::date;\n  v_end := (date_trunc('month', p_salary_month) + interval '1 month - 1 day')::date;\n\n  RETURN coalesce(\n    (SELECT jsonb_agg(to_jsonb(h) ORDER BY h.holiday_date)\n     FROM public.staff_salary_holidays h\n     WHERE h.holiday_date >= v_start AND h.holiday_date <= v_end),\n    '[]'::jsonb\n  );\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_upsert_staff_salary_holiday(\n  p_holiday_date date,\n  p_name text,\n  p_is_paid boolean DEFAULT true,\n  p_id uuid DEFAULT NULL\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_row public.staff_salary_holidays%ROWTYPE;\nBEGIN\n  PERFORM public._admin_assert_salary_access();\n\n  IF p_holiday_date IS NULL OR p_name IS NULL OR trim(p_name) = '' THEN\n    RAISE EXCEPTION 'Holiday date and name are required';\n  END IF;\n\n  IF p_id IS NULL THEN\n    INSERT INTO public.staff_salary_holidays (holiday_date, name, is_paid, created_by)\n    VALUES (p_holiday_date, trim(p_name), coalesce(p_is_paid, true), auth.uid())\n    ON CONFLICT (holiday_date) DO UPDATE\n    SET name = EXCLUDED.name, is_paid = EXCLUDED.is_paid\n    RETURNING * INTO v_row;\n  ELSE\n    UPDATE public.staff_salary_holidays\n    SET holiday_date = p_holiday_date,\n        name = trim(p_name),\n        is_paid = coalesce(p_is_paid, true)\n    WHERE id = p_id\n    RETURNING * INTO v_row;\n    IF NOT FOUND THEN RAISE EXCEPTION 'Holiday not found'; END IF;\n  END IF;\n\n  RETURN to_jsonb(v_row);\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_delete_staff_salary_holiday(p_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  PERFORM public._admin_assert_salary_access();\n  DELETE FROM public.staff_salary_holidays WHERE id = p_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Holiday not found'; END IF;\n  RETURN jsonb_build_object('ok', true);\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_upsert_staff_paid_leave_grant(\n  p_employee_id uuid,\n  p_salary_month date,\n  p_extra_paid_days numeric,\n  p_reason text DEFAULT NULL\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_month date := date_trunc('month', p_salary_month)::date;\n  v_row public.staff_paid_leave_grants%ROWTYPE;\nBEGIN\n  PERFORM public._admin_assert_salary_access();\n\n  IF p_employee_id IS NULL THEN\n    RAISE EXCEPTION 'Employee is required';\n  END IF;\n\n  INSERT INTO public.staff_paid_leave_grants (\n    employee_id, salary_month, extra_paid_days, reason, granted_by, updated_at\n  )\n  VALUES (\n    p_employee_id,\n    v_month,\n    greatest(coalesce(p_extra_paid_days, 0), 0),\n    nullif(trim(coalesce(p_reason, '')), ''),\n    auth.uid(),\n    now()\n  )\n  ON CONFLICT (employee_id, salary_month) DO UPDATE\n  SET extra_paid_days = EXCLUDED.extra_paid_days,\n      reason = EXCLUDED.reason,\n      granted_by = auth.uid(),\n      updated_at = now()\n  RETURNING * INTO v_row;\n\n  RETURN to_jsonb(v_row);\nEND;\n$$;\n","CREATE OR REPLACE FUNCTION public.admin_list_staff_paid_leave_grants(p_salary_month date)\nRETURNS jsonb\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_month date := date_trunc('month', p_salary_month)::date;\nBEGIN\n  PERFORM public._admin_assert_salary_access();\n  RETURN coalesce(\n    (SELECT jsonb_agg(to_jsonb(g) ORDER BY g.created_at DESC)\n     FROM public.staff_paid_leave_grants g\n     WHERE g.salary_month = v_month),\n    '[]'::jsonb\n  );\nEND;\n$$;\n","CREATE OR REPLACE FUNCTION public.admin_generate_staff_salary(\n  p_employee_id uuid,\n  p_salary_month date\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_month date := date_trunc('month', p_salary_month)::date;\n  v_month_end date := (date_trunc('month', p_salary_month) + interval '1 month - 1 day')::date;\n  v_setup public.staff_salary_setup%ROWTYPE;\n  v_present numeric := 0;\n  v_absent numeric := 0;\n  v_leave_paid numeric := 0;\n  v_leave_unpaid numeric := 0;\n  v_half numeric := 0;\n  v_holiday_att numeric := 0;\n  v_festival numeric := 0;\n  v_festival_paid numeric := 0;\n  v_overtime_hours numeric := 0;\n  v_overtime_amount numeric := 0;\n  v_gross numeric;\n  v_fixed_deductions numeric;\n  v_per_day numeric;\n  v_hourly numeric;\n  v_std_hours numeric;\n  v_ot_mult numeric;\n  v_paid_quota numeric;\n  v_extra_grant numeric := 0;\n  v_paid_pool numeric;\n  v_paid_used numeric := 0;\n  v_half_deduction numeric := 0;\n  v_absent_deduction numeric := 0;\n  v_unpaid_leave_deduction numeric := 0;\n  v_attendance_deduction numeric;\n  v_net numeric;\n  v_breakdown jsonb;\n  v_slip_id uuid;\n  v_leave_req record;\n  v_d date;\n  v_days_in_range numeric;\n  v_has_att boolean;\n  v_is_festival boolean;\n  v_leave_needs_paid numeric;\n  v_leave_overflow numeric;\nBEGIN\n  PERFORM public._admin_assert_salary_access();\n\n  IF p_employee_id IS NULL OR v_month IS NULL THEN\n    RAISE EXCEPTION 'Employee and salary month are required';\n  END IF;\n\n  SELECT * INTO v_setup\n  FROM public.staff_salary_setup s\n  WHERE s.employee_id = p_employee_id AND s.is_active IS TRUE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Payment setup missing for this staff member';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.staff_salary_slips ss\n    WHERE ss.employee_id = p_employee_id\n      AND ss.salary_month = v_month\n      AND ss.status = 'paid'\n  ) THEN\n    RAISE EXCEPTION 'Salary already paid for this month — cannot regenerate';\n  END IF;\n\n  v_std_hours := greatest(coalesce(v_setup.standard_hours_per_day, 8), 1);\n  v_ot_mult := greatest(coalesce(v_setup.overtime_multiplier, 1.5), 1);\n\n  -- Attendance aggregates\n  SELECT\n    coalesce(sum(CASE WHEN ea.status IN ('present', 'overtime') THEN 1 ELSE 0 END), 0),\n    coalesce(sum(CASE WHEN ea.status = 'absent' THEN 1 ELSE 0 END), 0),\n    coalesce(sum(CASE WHEN ea.status = 'leave' THEN 1 ELSE 0 END), 0),\n    coalesce(sum(CASE WHEN ea.status = 'half_day' THEN 1 ELSE 0 END), 0),\n    coalesce(sum(CASE WHEN ea.status = 'holiday' THEN 1 ELSE 0 END), 0),\n    0::numeric\n  INTO v_present, v_absent, v_leave_paid, v_half, v_holiday_att, v_overtime_hours\n  FROM public.employee_attendance ea\n  WHERE ea.employee_id = p_employee_id\n    AND ea.attendance_date >= v_month\n    AND ea.attendance_date <= v_month_end;\n\n  -- Recompute overtime hours correctly (second pass for OT only)\n  SELECT coalesce(sum(\n    GREATEST(\n      0,\n      CASE\n        WHEN ea.status = 'overtime' THEN v_std_hours\n        ELSE public._staff_salary_worked_hours(ea.check_in_at, ea.check_out_at)\n      END - v_std_hours\n    )\n  ), 0)\n  INTO v_overtime_hours\n  FROM public.employee_attendance ea\n  WHERE ea.employee_id = p_employee_id\n    AND ea.attendance_date >= v_month\n    AND ea.attendance_date <= v_month_end\n    AND ea.status IN ('present', 'overtime', 'half_day');\n\n  -- Paid festival / company holidays (not already marked in attendance)\n  SELECT coalesce(count(*), 0),\n         coalesce(count(*) FILTER (WHERE h.is_paid IS TRUE), 0)\n  INTO v_festival, v_festival_paid\n  FROM public.staff_salary_holidays h\n  WHERE h.holiday_date >= v_month AND h.holiday_date <= v_month_end\n    AND NOT EXISTS (\n      SELECT 1 FROM public.employee_attendance ea\n      WHERE ea.employee_id = p_employee_id\n        AND ea.attendance_date = h.holiday_date\n    );\n\n  -- Extra paid leave grant for this employee + month\n  SELECT coalesce(g.extra_paid_days, 0) INTO v_extra_grant\n  FROM public.staff_paid_leave_grants g\n  WHERE g.employee_id = p_employee_id AND g.salary_month = v_month;\n\n  v_paid_quota := coalesce(v_setup.paid_leaves_per_month, 0) + coalesce(v_extra_grant, 0);\n  v_paid_pool := v_paid_quota + v_festival_paid + v_holiday_att;\n\n  -- Approved leave requests: fill days without attendance rows\n  FOR v_leave_req IN\n    SELECT lr.leave_type, lr.from_date, lr.to_date\n    FROM public.staff_leave_requests lr\n    WHERE lr.staff_id = p_employee_id\n      AND lr.status = 'approved'\n      AND lr.to_date >= v_month\n      AND lr.from_date <= v_month_end\n  LOOP\n    v_d := greatest(v_leave_req.from_date, v_month);\n    WHILE v_d <= least(v_leave_req.to_date, v_month_end) LOOP\n      SELECT EXISTS (\n        SELECT 1 FROM public.employee_attendance ea\n        WHERE ea.employee_id = p_employee_id AND ea.attendance_date = v_d\n      ) INTO v_has_att;\n\n      IF NOT v_has_att THEN\n        SELECT EXISTS (\n          SELECT 1 FROM public.staff_salary_holidays h\n          WHERE h.holiday_date = v_d AND h.is_paid IS TRUE\n        ) INTO v_is_festival;\n\n        IF v_is_festival THEN\n          NULL; -- festival already counted\n        ELSIF v_leave_req.leave_type = 'unpaid' THEN\n          v_leave_unpaid := v_leave_unpaid + 1;\n        ELSE\n          v_leave_paid := v_leave_paid + 1;\n        END IF;\n      END IF;\n      v_d := v_d + 1;\n    END LOOP;\n  END LOOP;\n\n  -- Split attendance 'leave' into paid vs unpaid using pool\n  v_leave_needs_paid := v_leave_paid;\n  v_paid_used := least(v_leave_needs_paid, v_paid_pool);\n  v_leave_overflow := greatest(0, v_leave_needs_paid - v_paid_used);\n  v_leave_unpaid := v_leave_unpaid + v_leave_overflow;\n  v_leave_paid := v_paid_used;\n\n  v_gross :=\n    coalesce(v_setup.basic_salary, 0)\n    + coalesce(v_setup.hra, 0)\n    + coalesce(v_setup.special_allowance, 0)\n    + coalesce(v_setup.other_allowances, 0);\n\n  v_fixed_deductions :=\n    coalesce(v_setup.pf_deduction, 0)\n    + coalesce(v_setup.tax_deduction, 0)\n    + coalesce(v_setup.other_deductions, 0);\n\n  v_per_day := CASE\n    WHEN v_setup.working_days_per_month > 0 THEN v_gross / v_setup.working_days_per_month\n    ELSE 0\n  END;\n\n  v_hourly := CASE\n    WHEN v_setup.working_days_per_month > 0 THEN v_gross / (v_setup.working_days_per_month * v_std_hours)\n    ELSE 0\n  END;\n\n  -- Deductions: absent (full), unpaid leave (full), half-day (50% each)\n  v_absent_deduction := round((v_absent * v_per_day)::numeric, 2);\n  v_unpaid_leave_deduction := round((v_leave_unpaid * v_per_day)::numeric, 2);\n  v_half_deduction := round((v_half * v_per_day * 0.5)::numeric, 2);\n\n  v_attendance_deduction := v_absent_deduction + v_unpaid_leave_deduction + v_half_deduction;\n\n  v_overtime_amount := round((v_overtime_hours * v_hourly * v_ot_mult)::numeric, 2);\n\n  v_net := greatest(\n    0,\n    round((v_gross - v_fixed_deductions - v_attendance_deduction + v_overtime_amount)::numeric, 2)\n  );\n\n  v_breakdown := jsonb_build_object(\n    'basic_salary', v_setup.basic_salary,\n    'hra', v_setup.hra,\n    'special_allowance', v_setup.special_allowance,\n    'other_allowances', v_setup.other_allowances,\n    'pf_deduction', v_setup.pf_deduction,\n    'tax_deduction', v_setup.tax_deduction,\n    'other_deductions', v_setup.other_deductions,\n    'working_days_per_month', v_setup.working_days_per_month,\n    'paid_leaves_per_month', v_setup.paid_leaves_per_month,\n    'extra_paid_leave_grant', v_extra_grant,\n    'paid_leave_quota_total', v_paid_quota,\n    'standard_hours_per_day', v_std_hours,\n    'overtime_multiplier', v_ot_mult,\n    'per_day_rate', round(v_per_day::numeric, 2),\n    'hourly_rate', round(v_hourly::numeric, 2),\n    'festival_holidays_count', v_festival_paid + v_holiday_att,\n    'festival_from_calendar', v_festival_paid,\n    'holiday_attendance_marked', v_holiday_att,\n    'paid_leave_days_used', v_leave_paid,\n    'unpaid_leave_days', v_leave_unpaid,\n    'half_days', v_half,\n    'absent_deduction', v_absent_deduction,\n    'unpaid_leave_deduction', v_unpaid_leave_deduction,\n    'half_day_deduction', v_half_deduction,\n    'overtime_hours', round(v_overtime_hours::numeric, 2),\n    'overtime_amount', v_overtime_amount,\n    'payment_mode', v_setup.payment_mode\n  );\n\n  INSERT INTO public.staff_salary_slips (\n    employee_id, salary_month,\n    present_days, absent_days, leave_days, half_days,\n    gross_amount, attendance_deduction, total_deductions, net_amount,\n    overtime_hours, overtime_amount, festival_days, unpaid_leave_days, half_day_deduction,\n    status, breakdown, generated_by, updated_at\n  )\n  VALUES (\n    p_employee_id, v_month,\n    round((v_present + v_half * 0.5 + v_festival_paid + v_holiday_att + v_leave_paid)::numeric, 2),\n    v_absent,\n    v_leave_paid,\n    v_half,\n    round(v_gross::numeric, 2),\n    v_attendance_deduction,\n    round((v_fixed_deductions + v_attendance_deduction)::numeric, 2),\n    v_net,\n    round(v_overtime_hours::numeric, 2),\n    v_overtime_amount,\n    v_festival_paid + v_holiday_att,\n    v_leave_unpaid,\n    v_half_deduction,\n    'generated',\n    v_breakdown,\n    auth.uid(),\n    now()\n  )\n  ON CONFLICT (employee_id, salary_month)\n  DO UPDATE SET\n    present_days = EXCLUDED.present_days,\n    absent_days = EXCLUDED.absent_days,\n    leave_days = EXCLUDED.leave_days,\n    half_days = EXCLUDED.half_days,\n    gross_amount = EXCLUDED.gross_amount,\n    attendance_deduction = EXCLUDED.attendance_deduction,\n    total_deductions = EXCLUDED.total_deductions,\n    net_amount = EXCLUDED.net_amount,\n    overtime_hours = EXCLUDED.overtime_hours,\n    overtime_amount = EXCLUDED.overtime_amount,\n    festival_days = EXCLUDED.festival_days,\n    unpaid_leave_days = EXCLUDED.unpaid_leave_days,\n    half_day_deduction = EXCLUDED.half_day_deduction,\n    status = CASE WHEN public.staff_salary_slips.status = 'paid' THEN 'paid' ELSE 'generated' END,\n    breakdown = EXCLUDED.breakdown,\n    generated_at = now(),\n    generated_by = auth.uid(),\n    updated_at = now()\n  WHERE public.staff_salary_slips.status <> 'paid'\n  RETURNING id INTO v_slip_id;\n\n  RETURN jsonb_build_object(\n    'ok', true,\n    'slip_id', v_slip_id,\n    'employee_id', p_employee_id,\n    'salary_month', v_month,\n    'net_amount', v_net,\n    'overtime_amount', v_overtime_amount,\n    'attendance_deduction', v_attendance_deduction,\n    'status', 'generated',\n    'breakdown', v_breakdown\n  );\nEND;\n$$;\n","GRANT EXECUTE ON FUNCTION public.admin_list_staff_salary_holidays(date) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.admin_upsert_staff_salary_holiday(date, text, boolean, uuid) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.admin_delete_staff_salary_holiday(uuid) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.admin_upsert_staff_paid_leave_grant(uuid, date, numeric, text) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.admin_list_staff_paid_leave_grants(date) TO authenticated;"];
export function staffSalaryAdvancedSql(): string {
  return STAFF_SALARY_ADVANCED_CHUNKS.join("");
}

